from collections import defaultdict

def f(N: int, M: int, edges: List[Tuple[int, int]]) -> int:
    parent = list(range(N+1))
    def find(x):
        if parent[x]!= x:
            parent[x] = find(parent[x])
        return parent[x]

    counter = defaultdict(int)
    for a, b in edges:
        pa = find(a)
        pb = find(b)
        if pa == pb:
            counter[pa] += 1
        else:
            parent[pa] = pb
    return max(counter.values())
